            if (Math.abs(n[2])<0.000001) continue;
            const dx=x-a[0],dy=y-a[1];
            const det=u[0]*v[1]-u[1]*v[0];
            const b=(dx*v[1]-dy*v[0])/det,c=(u[0]*dy-u[1]*dx)/det;
            if (b<-0.000001 || c<-0.000001 || b+c>1.000001) continue;
