        const floors = [["Bob-omb Battlefield",3330160,22528,"rgba",16,32,32],["Cool, Cool Mountain",3412288,34816,"rgba",16,32,32],["Whomp’s Fortress",3502928,30720,"rgba",16,32,32],["Jolly Roger Bay",3361584,10240,"rgba",16,64,32],["Big Boo’s Haunt",3305024,36864,"rgba",16,64,32],["Hazy Maze Cave",3439184,38912,"rgba",16,32,32],["Shifting Sand Land",3330160,32768,"rgba",16,32,32],["Lethal Lava Land",3269072,14336,"rgba",16,32,32],["Dire, Dire Docks",3361584,30720,"rgba",16,64,32],["Snowman’s Land",4218800,8192,"rgba",16,32,32],["Wet-Dry World",3502928,28672,"rgba",16,32,32],["Tall, Tall Mountain",3479904,14336,"rgba",16,32,32],["Tiny-Huge Island",3502928,22528,"rgba",16,32,32],["Tick Tock Clock",3467104,28672,"rgba",16,32,32],["Rainbow Ride",4421744,0,"rgba",16,32,32],["Interior do castelo",3561856,16384,"rgba",16,32,32],["Pátio do castelo",3534096,40960,"rgba",16,32,32],["Princess’s Secret Slide",4913456,0,"rgba",16,32,32],["Cavern of the Metal Cap",4948176,8192,"rgba",16,32,32],["Vanish Cap Under the Moat",3534096,45056,"rgba",16,16,32],["Wing Mario Over the Rainbow",4997920,0,"rgba",16,32,32]];
