                            cache[first + i] = [rom.getInt16(p), rom.getInt16(p + 4), rom.getInt16(p + 2),
                                rom.getInt16(p + 8), rom.getInt16(p + 10),
                                rom.getUint8(p + 12), rom.getUint8(p + 13),
                                rom.getUint8(p + 14), rom.getUint8(p + 15)];
